/*
 * ESP32 I2S Online Music Player with Playback Controls
 *
 * Buttons:
 *   D2 = Play / Pause
 *   D3 = Next track
 *   D4 = Previous track
 *
 * I2S DAC (MAX98357A):
 *   D26 = BCLK,  D25 = LRC,  D22 = DIN
 *
 * The sketch generates synthetic PCM audio at different
 * frequencies for each "track" so you can hear the
 * transitions when pressing Next / Previous.
 */

#include <WiFi.h>
#include <HTTPClient.h>
#include <driver/i2s.h>

// --- WiFi credentials ---
const char* ssid     = "YOUR_WIFI_SSID";
const char* password = "YOUR_WIFI_PASS";

// --- I2S Configuration ---
#define I2S_PORT       I2S_NUM_0
#define I2S_BCLK_PIN   26
#define I2S_LRCK_PIN   25
#define I2S_DOUT_PIN   22
#define I2S_BUF_SIZE   1024
#define I2S_BUF_COUNT  4

// --- Button pins ---
#define BTN_PLAY_PIN   2
#define BTN_NEXT_PIN   3
#define BTN_PREV_PIN   4

// --- Track list (frequencies in Hz) ---
const int TRACK_FREQS[]  = { 262, 330, 392, 440, 523 };
const char* TRACK_NAMES[] = { "Do (C4)", "Mi (E4)", "Sol (G4)", "La (A4)", "Do (C5)" };
const int NUM_TRACKS = 5;

// --- Playback state ---
bool playing        = false;
int  currentTrack   = 0;
bool lastPlayState  = HIGH;
bool lastNextState  = HIGH;
bool lastPrevState  = HIGH;
unsigned long lastDebounce = 0;
#define DEBOUNCE_MS 200

void setupI2S() {
  i2s_config_t i2s_config = {
    .mode                 = (i2s_mode_t)(I2S_MODE_MASTER | I2S_MODE_TX),
    .sample_rate          = 44100,
    .bits_per_sample      = I2S_BITS_PER_SAMPLE_16BIT,
    .channel_format       = I2S_CHANNEL_FMT_RIGHT_LEFT,
    .communication_format = I2S_COMM_FORMAT_STAND_I2S,
    .intr_alloc_flags     = ESP_INTR_FLAG_LEVEL1,
    .dma_buf_count        = I2S_BUF_COUNT,
    .dma_buf_len          = I2S_BUF_SIZE,
    .use_apll             = false,
    .tx_desc_auto_clear   = true,
  };

  i2s_pin_config_t pin_config = {
    .bck_io_num   = I2S_BCLK_PIN,
    .ws_io_num    = I2S_LRCK_PIN,
    .data_out_num = I2S_DOUT_PIN,
    .data_in_num  = I2S_PIN_NO_CHANGE,
  };

  i2s_driver_install(I2S_PORT, &i2s_config, 0, NULL);
  i2s_set_pin(I2S_PORT, &pin_config);
  i2s_zero_dma_buffer(I2S_PORT);
  Serial.println("[I2S] Driver initialized");
}

void setup() {
  Serial.begin(115200);
  delay(1000);
  Serial.println("\n=== ESP32 I2S Music Player ===");

  // Button inputs with internal pull-ups
  pinMode(BTN_PLAY_PIN, INPUT_PULLUP);
  pinMode(BTN_NEXT_PIN, INPUT_PULLUP);
  pinMode(BTN_PREV_PIN, INPUT_PULLUP);

  // Connect to WiFi
  Serial.printf("[WIFI] Connecting to %s", ssid);
  WiFi.begin(ssid, password);
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.printf("\n[WIFI] Connected! IP: %s\n", WiFi.localIP().toString().c_str());

  setupI2S();
  Serial.println("[MUSIC] Ready. Press buttons to control playback.");
  Serial.printf("[MUSIC] Track 1/%d: %s (%d Hz)\n", NUM_TRACKS, TRACK_NAMES[currentTrack], TRACK_FREQS[currentTrack]);
}

void playTrack() {
  int freq = TRACK_FREQS[currentTrack];
  int sr = 44100, channels = 2, bps = 2;
  int totalSamples = sr * channels;  // 1 second
  uint8_t buffer[I2S_BUF_SIZE];

  Serial.printf("[MUSIC] Playing: %s (%d Hz)\n", TRACK_NAMES[currentTrack], freq);

  unsigned long startTime = millis();
  while (playing && (millis() - startTime < 3000)) {  // play 3 seconds
    int samplesInBuf = I2S_BUF_SIZE / bps / channels;
    int16_t* samples = (int16_t*)buffer;

    for (int i = 0; i < samplesInBuf * channels; i += 2) {
      float t = (float)(startTime + (millis() - startTime)) / 1000.0;
      int16_t s = (int16_t)(16000.0 * sin(2.0 * 3.14159 * freq * t));
      samples[i]     = s;  // left
      samples[i + 1] = s;  // right
    }

    size_t written = 0;
    i2s_write(I2S_PORT, buffer, I2S_BUF_SIZE, &written, portMAX_DELAY);

    // Check buttons during playback
    checkButtons();
  }
}

void checkButtons() {
  unsigned long now = millis();
  if (now - lastDebounce < DEBOUNCE_MS) return;

  bool playState = digitalRead(BTN_PLAY_PIN);
  bool nextState = digitalRead(BTN_NEXT_PIN);
  bool prevState = digitalRead(BTN_PREV_PIN);

  // Play / Pause
  if (playState == LOW && lastPlayState == HIGH) {
    playing = !playing;
    Serial.printf("[CTRL] %s\n", playing ? "PLAY" : "PAUSE");
    lastDebounce = now;
  }
  lastPlayState = playState;

  // Next track
  if (nextState == LOW && lastNextState == HIGH) {
    currentTrack = (currentTrack + 1) % NUM_TRACKS;
    playing = true;
    Serial.printf("[CTRL] NEXT -> Track %d/%d: %s\n", currentTrack + 1, NUM_TRACKS, TRACK_NAMES[currentTrack]);
    lastDebounce = now;
  }
  lastNextState = nextState;

  // Previous track
  if (prevState == LOW && lastPrevState == HIGH) {
    currentTrack = (currentTrack - 1 + NUM_TRACKS) % NUM_TRACKS;
    playing = true;
    Serial.printf("[CTRL] PREV -> Track %d/%d: %s\n", currentTrack + 1, NUM_TRACKS, TRACK_NAMES[currentTrack]);
    lastDebounce = now;
  }
  lastPrevState = prevState;
}

void loop() {
  if (WiFi.status() != WL_CONNECTED) {
    Serial.println("[WIFI] Disconnected. Reconnecting...");
    WiFi.reconnect();
    while (WiFi.status() != WL_CONNECTED) delay(500);
  }

  checkButtons();

  if (playing) {
    playTrack();
  } else {
    delay(100);
  }
}
